@pytest.mark.intent
def test_interrupted_run_keeps_its_settings(tmp_path: Path) -> None:
    _interrupted_run(tmp_path)
    folder = _run_folder(tmp_path)
    assert (folder / "settings.json").is_file()


class _GreedyInterruptedAgent(_InterruptedAgent):
    """Interrupted on its `greedy_limit`-th greedy `act`: inside an evaluation."""

    def __init__(self, greedy_limit: int) -> None:
        super().__init__()
        self.greedy = 0
        self.greedy_limit = greedy_limit

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        if not explore:
            self.greedy += 1
            if self.greedy == self.greedy_limit:
                raise KeyboardInterrupt
        return np.ones((obs.shape[0],), dtype=np.int64)

    def learn(self, t: Transition) -> None:
        self.learns += 1


class _ArmedAgent(_InterruptedAgent):
    """Arms the environment after INTERRUPT_AT_LEARN - 1 learns instead of raising itself."""

    def __init__(self) -> None:
        super().__init__()
        self.armed = False

    def learn(self, t: Transition) -> None:
        self.learns += 1
        if self.learns == INTERRUPT_AT_LEARN - 1:
            self.armed = True


@pytest.mark.intent
def test_interrupt_in_the_environment_step_keeps_the_run_incomplete(tmp_path: Path) -> None:
    agent = _ArmedAgent()

    class _TrippedEnv(_LoopEnv):
        def step(self, actions: Any) -> StepResult:
            if agent.armed:
                raise KeyboardInterrupt
            return super().step(actions)

    with pytest.raises(KeyboardInterrupt):
        train(_TrippedEnv, {SOLO: agent}, _settings(), root=tmp_path)
    folder = _run_folder(tmp_path)
    assert (folder / "status").read_text(encoding="utf-8").strip() == "incomplete"
    assert len(_curve_rows(folder)) == 3


@pytest.mark.intent
def test_interrupt_during_an_evaluation_keeps_the_finished_points(tmp_path: Path) -> None:
    # Three evaluations of eval_games=2 games of GAME_LENGTH greedy acts finish first.
    agent = _GreedyInterruptedAgent(3 * 2 * GAME_LENGTH + GAME_LENGTH)
    with pytest.raises(KeyboardInterrupt):
        train(_LoopEnv, {SOLO: agent}, _settings(), root=tmp_path)
    folder = _run_folder(tmp_path)
    assert (folder / "status").read_text(encoding="utf-8").strip() == "incomplete"
    assert len(_curve_rows(folder)) == 3

